<div class="court-preview" id="courtPreview" aria-hidden="true"><div class="court-preview-panel"><button class="court-preview-close" type="button" aria-label="Đóng">×</button><div id="courtPreviewContent"></div></div></div>
<script>
const courtPreviewData = @json($courtPreviewData);
const preview = document.getElementById('courtPreview'), previewContent = document.getElementById('courtPreviewContent');
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, c => '&' + '#' + c.charCodeAt(0) + ';');
const starHtml = rating => { const rounded = Math.round(Number(rating)); let stars = ''; for (let i = 1; i <= 5; i++) stars += `<i class="bi bi-star${i <= rounded ? '-fill' : ''}"></i>`; return stars; };
function openCourtPreview(id, bookingUrl) {
    const court = courtPreviewData[id]; if (!court) return;
    window.cpImages = court.images;
    const mainBlock = court.images.length
        ? `<img id="cpMainImg" src="${escapeHtml(court.images[0])}" alt="${escapeHtml(court.name)}">`
        : '<div class="cp-fallback"><i class="bi bi-trophy-fill"></i></div>';
    const typeBadge = court.type ? `<span class="cp-type">${escapeHtml(court.type)}</span>` : '';
    const thumbs = court.images.length > 1
        ? `<div class="cp-thumbs">${court.images.map((image, i) => `<button type="button" class="cp-thumb ${i === 0 ? 'active' : ''}" onclick="switchPreviewImage(${i}, this)"><img src="${escapeHtml(image)}" alt="Ảnh ${i + 1}"></button>`).join('')}</div>`
        : '';
    const rating = court.rating
        ? `<span class="stars">${starHtml(court.rating)}</span><span>${court.rating}</span><small>(${court.reviews_count} đánh giá)</small>`
        : '<span class="stars"><i class="bi bi-stars"></i></span><small>Sân chất lượng</small>';
    const phone = court.phone ? `<p class="cp-meta"><i class="bi bi-telephone-fill"></i><span><strong>Hotline:</strong> ${escapeHtml(court.phone)}</span></p>` : '';
    const hours = court.opening && court.closing ? `<p class="cp-meta"><i class="bi bi-clock-fill"></i><span><strong>Giờ mở cửa:</strong> Thứ 2 - CN: ${court.opening} - ${court.closing}</span></p>` : '';
    const amenities = court.amenities.length ? `<div class="cp-block"><h3>Tiện ích</h3><div class="cp-amenities">${court.amenities.map(item => `<span><i class="bi bi-check-circle-fill"></i>${escapeHtml(item)}</span>`).join('')}</div></div>` : '';
    previewContent.innerHTML = `
        <div class="cp-grid">
            <div class="cp-gallery">
                <div class="cp-main">${mainBlock}${typeBadge}</div>${thumbs}
            </div>
            <div class="cp-info">
                ${court.type ? `<span class="cp-kicker">${escapeHtml(court.type)}</span>` : ''}
                <h2>${escapeHtml(court.name)}</h2>
                <div class="cp-rating">${rating}</div>
                <div class="cp-contact">
                    <p class="cp-meta"><i class="bi bi-geo-alt-fill"></i><span><strong>Địa chỉ:</strong> ${escapeHtml(court.address || 'Đang cập nhật')}</span></p>${phone}${hours}
                </div>
                ${amenities}
                <div class="cp-block cp-desc"><h3>Giới thiệu</h3><p>${escapeHtml(court.description || 'Sân được đầu tư khang trang, sạch đẹp với trang thiết bị hiện đại, phù hợp cho luyện tập và thi đấu.')}</p></div>
            </div>
        </div>
        <div class="court-preview-footer"><div class="court-preview-price"><small>GIÁ THUÊ TỪ</small><strong>${Number(court.price).toLocaleString('vi-VN')}đ <em>/giờ</em></strong></div><a class="court-preview-book" href="${escapeHtml(bookingUrl)}">Đặt sân ngay <i class="bi bi-arrow-right"></i></a></div>`;
    preview.classList.add('open'); preview.setAttribute('aria-hidden','false'); document.body.style.overflow = 'hidden';
}
window.switchPreviewImage = function(index, el) {
    const main = document.getElementById('cpMainImg');
    if (main && window.cpImages[index]) main.src = window.cpImages[index];
    document.querySelectorAll('.cp-thumb').forEach(thumb => thumb.classList.remove('active'));
    if (el) el.classList.add('active');
};
document.querySelectorAll('.court-link[href*="/courts/"]').forEach(link => link.addEventListener('click', event => { event.preventDefault(); const match = link.href.match(/\/courts\/(\d+)/); if (match) openCourtPreview(match[1], link.href); }));
function closeCourtPreview(){preview.classList.remove('open');preview.setAttribute('aria-hidden','true');document.body.style.overflow='';}
document.querySelector('.court-preview-close').addEventListener('click',closeCourtPreview);preview.addEventListener('click',event=>{if(event.target===preview)closeCourtPreview()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeCourtPreview()});
</script>
</body></html>
